def binary_search(a, target, low, high):
    while low <= high:
        mid = (low + high) // 2
        if a[mid] == target:
            return mid
        elif a[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def exponential_search(a, target):
    if a[0] == target:
        return 0
    bound = 1
    while bound < len(a) and a[bound] <= target:
        bound *= 2
    return binary_search(a, target, bound // 2, min(bound, len(a) - 1))

